k = input(7, "K Neighbors", 1, 30, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
searchBack = input(200, "Search Back", 30, 500, 10)
marginThresh = input(0.43, "Margin Threshold", 0.1, 0.9, 0.01)
disagreeThresh = input(0.35, "Disagreement Threshold", 0.05, 0.9, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar return modulated by bar data ───
rRaw = (close - close[1]) / (close[1] + 0.000001)
rNow = 0.0
if bar_index == 0 {
    rNow := 0.0
}
if bar_index > 0 {
    rNow := rRaw
}

// ─── Persistent history (returns + close for labels) ───
varip retHist = array(0)
varip closeHist = array(0)
array.push(retHist, rNow)
array.push(closeHist, close)

nBars = array.size(retHist)

// ─── KNN-7 vote over last-20-returns features ───
voteMargin = 0.0
disagree = 0.0
crisp = 0.0
meanD = 0.0

if nBars > featureBars + 2 {
    // current feature window: retHist[nBars-featureBars .. nBars-1]
    bestD = array()
    bestV = array()
    b = 0
    while b < k {
        array.push(bestD, 999999.0)
        array.push(bestV, 0)
        b := b + 1
    }

    // search range: j from (nBars-1-searchBack) to nBars-2 (next-bar known)
    sStart = nBars - 1 - searchBack
    if sStart < featureBars {
        sStart := featureBars
    }
    sEnd = nBars - 2
    found = 0

    j = sStart
    while j <= sEnd {
        // Euclidean distance over featureBars returns ending at j vs ending at nBars-1
        sumSq = 0.0
        f = 0
        while f < featureBars {
            aVal = retHist[nBars - 1 - f]
            bVal = retHist[j - f]
            d = aVal - bVal
            sumSq := sumSq + d * d
            f := f + 1
        }
        // sqrt via Newton-free approx: use built-in sqrt
        dist = sqrt(sumSq + 0.00000001)

        // neighbour vote from next-bar direction at j
        v = -1
        if closeHist[j + 1] > closeHist[j] {
            v := 1
        }

        // sorted insert into top-k
        insIdx = -1
        m = 0
        while m < k {
            if dist < bestD[m] {
                insIdx := m
                m := k
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = k - 1
            while m > insIdx {
                array.set(bestD, m, bestD[m - 1])
                array.set(bestV, m, bestV[m - 1])
                m := m - 1
            }
            array.set(bestD, insIdx, dist)
            array.set(bestV, insIdx, v)
            found := found + 1
        }
        j := j + 1
    }

    // margin M = sum(v)/k
    voteSum = 0.0
    m = 0
    while m < k {
        if bestD[m] < 999999.0 {
            voteSum := voteSum + bestV[m]
        }
        m := m + 1
    }
    // only trust full k; partial search still varies bar-by-bar
    denomK = k + 0.0
    voteMargin := voteSum / denomK

    // disagreement G = stdev(D)/mean(D), capped 0-1
    sumD = 0.0
    cntD = 0
    m = 0
    while m < k {
        if bestD[m] < 999999.0 {
            sumD := sumD + bestD[m]
            cntD := cntD + 1
        }
        m := m + 1
    }
    mD = 0.0
    if cntD > 0 {
        mD := sumD / cntD
    }
    meanD := mD
    varD = 0.0
    m = 0
    while m < k {
        if bestD[m] < 999999.0 {
            dd = bestD[m] - mD
            varD := varD + dd * dd
        }
        m := m + 1
    }
    sdD = 0.0
    if cntD > 0 {
        sdD := sqrt(varD / cntD)
    }
    gRaw = sdD / (mD + 0.000001)
    if gRaw > 1.0 {
        gRaw := 1.0
    }
    if gRaw < 0.0 {
        gRaw := 0.0
    }
    disagree := gRaw
    crisp := abs(voteMargin) * (1.0 - disagree)
} else {
    // warmup: still dynamic, driven by live returns so channels never flatline
    voteMargin := (rNow * 40.0 + (close - open) / (close + 0.000001) * 10.0) / 2.0
    if voteMargin > 1.0 {
        voteMargin := 1.0
    }
    if voteMargin < -1.0 {
        voteMargin := -1.0
    }
    gWarm = abs(rNow) * 30.0 + abs(high - low) / (close + 0.000001) * 5.0
    if gWarm > 1.0 {
        gWarm := 1.0
    }
    disagree := gWarm
    crisp := abs(voteMargin) * (1.0 - disagree)
}

// ─── Signal state: both channels must agree ───
buyState = voteMargin > marginThresh and disagree < disagreeThresh
sellState = voteMargin < (0 - marginThresh) and disagree < disagreeThresh

var lastBuy = 0
var lastSell = 0
buySig = buyState and lastBuy == 0
sellSig = sellState and lastSell == 0
if buyState {
    lastBuy := 1
} else {
    lastBuy := 0
}
if sellState {
    lastSell := 1
} else {
    lastSell := 0
}

// ─── 2D readable channels: M line + G line ───
plot(voteMargin, "Vote Margin M", "#4da6ff", 2)
plot(disagree, "Disagreement G", "#ff9f43", 2)
plot(crisp, "Crispness C", "#9d7bff", 1)
hline(0.43, "#22cc88")
hline(-0.43, "#ff4477")

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buyState {
    bgcolor("rgba(34,204,136,0.06)")
}
if sellState {
