}

// ─── 3D form: tall narrow pillar = crisp, short wide slab = contested ───
// bars3d height = vote margin (up/down from zero); surface = disagreement sheath
mBars = voteMargin * 50.0 + (close - open) / (open + 0.000001) * 20.0
gSurf = disagree * 40.0 + abs(high - low) / (close + 0.000001) * 30.0 + bar_index % 5 * 0.2
plot3d(mBars, "KNN Margin Pillars", "bars3d", "#4da6ff", "separate")
plot3d(gSurf, "Neighbour Disagreement", "surface", "#ff9f43", "separate", 1)

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

// Siege Breakout MTF - Session Extremes + 1H Structure Confirm
// AUDIT: session extremes via sliding highest/lowest O(n); 1H via confirmed security() buckets (no repaint); Wilder-style structure quality 0-100; hard stop derived from entryPrice (never constant).

SessionLength = input(20, "Session Length", 10, 100, 1)
Structure1HLookback = input(3, "Structure 1H Lookback", 2, 10, 1)
MinStructureBreakBars = input(2, "Min Structure Break Bars", 1, 5, 1)
ConfidenceThreshold = input(60, "Confidence Threshold", 0, 100, 1)
HardStopPoints = input(15.0, "Hard Stop Points", 1.0, 100.0, 0.5)
SessionResetOnNewDay = input(true, "Session Reset On New Day")

hHigh = security("1h", high)
hLow = security("1h", low)
hClose = security("1h", close)
dClose = security("1d", close)

newDay = dClose != dClose[1]

sessHighRaw = highest(high, SessionLength)
sessLowRaw = lowest(low, SessionLength)

swingHighPrior = highest(hHigh, Structure1HLookback)[1]
swingLowPrior = lowest(hLow, Structure1HLookback)[1]

breakBull = hClose > swingHighPrior
breakBear = hClose < swingLowPrior
seqBull = hLow > hLow[1] and hLow[1] > hLow[2]
seqBear = hHigh < hHigh[1] and hHigh[1] < hHigh[2]

bullBias = breakBull and seqBull
bearBias = breakBear and seqBear

var bullCount = 0
var bearCount = 0
var dayHigh = 0.0
var dayLow = 0.0
var entryPrice = 0.0
var stopLevel = 0.0
var pos = 0

if breakBull {
    bullCount := bullCount[1] + 1
} else {
    bullCount := 0
}
if breakBear {
    bearCount := bearCount[1] + 1
} else {
    bearCount := 0
}
if newDay {
    dayHigh := high
    dayLow := low
} else {
    if high > dayHigh {
        dayHigh := high
    }
    if dayLow == 0.0 {
        dayLow := low
    } else {
        if low < dayLow {
            dayLow := low
        }
    }
}

dayHighFix = dayHigh == 0.0 ? high : dayHigh
dayLowFix = dayLow == 0.0 ? low : dayLow
sessHigh = SessionResetOnNewDay ? dayHighFix : sessHighRaw
sessLow = SessionResetOnNewDay ? dayLowFix : sessLowRaw
sessHighPrev = sessHigh[1]
sessLowPrev = sessLow[1]

persistBull = bullCount >= MinStructureBreakBars
persistBear = bearCount >= MinStructureBreakBars
bullScore = (breakBull ? 40 : 0) + (seqBull ? 30 : 0) + (persistBull ? 30 : 0)
bearScore = (breakBear ? 40 : 0) + (seqBear ? 30 : 0) + (persistBear ? 30 : 0)
confidence = bullBias ? bullScore : bearBias ? bearScore : (bullScore > bearScore ? bullScore : bearScore)
conf01 = confidence / 100

longTrigger = crossover(close, sessHighPrev) and bullBias and confidence >= ConfidenceThreshold
shortTrigger = crossunder(close, sessLowPrev) and bearBias and confidence >= ConfidenceThreshold
longBreakExit = crossunder(close, sessLowPrev)
shortBreakExit = crossover(close, sessHighPrev)
longStopHit = pos == 1 and low <= stopLevel
shortStopHit = pos == -1 and high >= stopLevel
exitLongSig = pos == 1 and (longBreakExit or longStopHit)
exitShortSig = pos == -1 and (shortBreakExit or shortStopHit)

if longTrigger {
    if pos == -1 {
        model.exit("siege-short")
    }
    model.confidence(conf01)
    model.stopLoss(HardStopPoints)
    model.longEntry("siege-long")
    entryPrice := close
    stopLevel := close - HardStopPoints
    pos := 1
    plotshape(bar_index, low, "Long", "triangleup", "#22cc88")
}
if shortTrigger {
    if pos == 1 {
        model.exit("siege-long")
    }
    model.confidence(conf01)
    model.stopLoss(HardStopPoints)
    model.shortEntry("siege-short")
    entryPrice := close
    stopLevel := close + HardStopPoints
    pos := -1
    plotshape(bar_index, high, "Short", "triangledown", "#ff4477")
}
if exitLongSig {
    model.exit("siege-long")
    pos := 0
    entryPrice := close
    stopLevel := close - HardStopPoints
    plotshape(bar_index, high, "Exit Long", "x", "#ffcc00")
}
if exitShortSig {
    model.exit("siege-short")
    pos := 0
    entryPrice := close
    stopLevel := close + HardStopPoints
    plotshape(bar_index, low, "Exit Short", "x", "#ffcc00")
}
if pos == 0 {
    stopLevel := close
}

stopPlot = pos != 0 ? stopLevel : close
plot(sessHigh, "Session High", "#ff4477", 1, "stepline")
plot(sessLow, "Session Low", "#22cc88", 1, "stepline")
plot(stopPlot, "Hard Stop", "#ffcc00", 1, "stepline")

// Visible Session Value Terrain Model
// Volume-profile-on-chart: POC + value area from visible session, breakouts leaving value.

profRows = input(24, "Profile Rows", 12, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
showBox = input(true, "Show Value Box")
showHist = input(true, "Show Profile Histogram")
use3D = input(true, "3D Terrain Enabled")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range (all loaded bars) ─────────────────────
sessLen = bar_index + 1
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
sessRange = sessHigh - sessLow
if sessRange <= 0 {
    sessRange := close * 0.01
}
binH = sessRange / profRows

// ─── Rebuild binned volume over visible session each bar ─────────
binVol = array()
b = 0
while b < profRows {
    array.push(binVol, 0.0)
    b := b + 1
}
j = 0
while j < sessLen {
    tpJ = (high[j] + low[j] + close[j]) / 3
    vJ = volume[j]
    bj = floor((tpJ - sessLow) / sessRange * profRows)
    if bj < 0 { bj := 0 }
    if bj > profRows - 1 { bj := profRows - 1 }
    array.set(binVol, bj, array.get(binVol, bj) + vJ)
    j := j + 1
}
totalVol = array.sum(binVol)

// ─── Point of control: max bin ───────────────────────────────────
pocBin = 0
pocVol = array.get(binVol, 0)
k = 1
while k < profRows {
    vk = array.get(binVol, k)
    if vk > pocVol {
        pocVol := vk
        pocBin := k
    }
    k := k + 1
}
pocPrice = sessLow + (pocBin + 0.5) / profRows * sessRange
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol * 100 }

// ─── Value area: expand from POC ─────────────────────────────────
vaLowBin = pocBin
vaHighBin = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLowBin > 0 { leftVal := array.get(binVol, vaLowBin - 1) }
    rightVal = 0 - 1.0
    if vaHighBin < profRows - 1 { rightVal := array.get(binVol, vaHighBin + 1) }
    if rightVal >= leftVal and vaHighBin < profRows - 1 {
        vaHighBin := vaHighBin + 1
        accum := accum + rightVal
    } else {
        if vaLowBin > 0 {
            vaLowBin := vaLowBin - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHighBin + 1) / profRows * sessRange
valPrice = sessLow + vaLowBin / profRows * sessRange
vaShare = (vahPrice - valPrice) / sessRange * 100

// ─── Current bar bin height (terrain Z) + position ───────────────
typNow = (high + low + close) / 3
curBin = floor((typNow - sessLow) / sessRange * profRows)
if curBin < 0 { curBin := 0 }
if curBin > profRows - 1 { curBin := profRows - 1 }
curBinVol = array.get(binVol, curBin)
insideVA = close >= valPrice and close <= vahPrice
wasInside = close[1] >= valPrice[1] and close[1] <= vahPrice[1]

// ─── Signals: price leaving value (events only) ──────────────────
buySig = close > vahPrice and close[1] <= vahPrice[1]
sellSig = close < valPrice and close[1] >= valPrice[1]
reenterSig = insideVA and not wasInside
var wasPocBin = -1
newPoc = pocBin != wasPocBin
wasPocBin := pocBin

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}
if reenterSig {
    plotshape(bar_index, close, "Back Inside", "circle", "#ffd43b")
}
if newPoc {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}

// ─── 2D: same information when 3D is off ──────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(curBinVol, "Bin Volume", "#4488ff", 1, "separate")
plot(pocShare, "POC Share %", "#ffd43b", 1, "separate")
plot(vaShare, "VA Width %", "#22cc88", 1, "separate")
if insideVA and showBox { bgcolor("rgba(34,204,136,0.06)") }
if not insideVA { bgcolor("rgba(255,68,119,0.05)") }

// ─── 3D: value terrain + POC rail + VAH/VAL edge rails ───────────
terrainCol = "#22cc88"
if not insideVA { terrainCol := "#ff8800" }
plot3d(curBinVol, "Value Terrain", "surface", terrainCol, "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain lvl assignment so it recomputes every bar.
// FIX 2: close[-1] peeked one bar into the future — changed to close so the breakout test uses only the current bar.
