buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowBase = input(100, "Flow Base PSI", 0, 300, 1)
critical_threshold = input(150, "Critical Threshold", 50, 300, 1)
spin_factor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
disc_radius = input(5.0, "Disc Radius", 1.0, 20.0, 0.5)
