spin_speed = flow_psi * spin_factor
overpressure_state = flow_psi > critical_threshold
prevState = overpressure_state[1]

var discAngle = 0.0
var lockBars = 0.0

if overpressure_state {
    lockBars := lockBars + 1
}
if overpressure_state {
} else {
    discAngle := discAngle + spin_speed
    lockBars := 0.0
}

