if overSig {
    plotshape_3d(bar_index, high, "OVERPRESSURE", "conedown", "#ff4477", markerSize, 0, "separate")
}
if recoverSig {
    plotshape_3d(bar_index, low, "Recover", "coneup", "#22cc88", markerSize, 1, "separate")
}
if overSig {
    label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 2, 1, "separate")
}

plot(flow_psi, "Flow PSI", "#33aaff", 2, "separate")
plot(discSpin, "Valve Disc Angle", "#ffaa00", 1, "separate")
plot(ringOuter, "Shock Ring", "#ff4477", 1, "separate")
plot3d(discSpin, "Valve Disc", "torus", "#ffaa00", "separate", 0)
plot3d(ringOuter, "Shock Rings", "line3d", "#ff4477", "separate", 1)
